```csharp
// ITask and CycleException are provided (Models.cs).
public class TaskManager {
    private readonly Dictionary<string, ITask> _tasks = new Dictionary<string, ITask>();
    private readonly Dictionary<string, List<string>> _dependsOn = new Dictionary<string, List<string>>();   // task -> its subtasks
    private readonly Dictionary<string, List<string>> _waitingOnMe = new Dictionary<string, List<string>>(); // subtask -> tasks it blocks
    private readonly Dictionary<string, int> _unfinished = new Dictionary<string, int>();                   // task -> deps not completed
    private readonly Queue<string> _ready = new Queue<string>();
    private readonly HashSet<string> _inReadyQueue = new HashSet<string>();
    private readonly HashSet<string> _handedOut = new HashSet<string>();
    private readonly HashSet<string> _completed = new HashSet<string>();

    public void AddTask(ITask task) {
        if (task == null) throw new ArgumentNullException(nameof(task));

        // ---- 1. Collect the new tasks and edges. Nothing in the manager changes yet.
        Dictionary<string, ITask> newTasks = new Dictionary<string, ITask>();
        Dictionary<string, List<string>> newEdges = new Dictionary<string, List<string>>();
        Stack<ITask> stack = new Stack<ITask>();
        stack.Push(task);
        while (stack.Count > 0) {
            ITask current = stack.Pop();
            string id = current.GetId();
            if (newTasks.ContainsKey(id)) continue;          // seen in this call already
            newTasks[id] = current;
            List<string> deps = new List<string>();
            IList<ITask> subs = current.GetSubTasks();
            if (subs != null) {
                foreach (ITask sub in subs) {
                    if (sub == null) continue;
                    deps.Add(sub.GetId());
                    stack.Push(sub);
                }
            }
            newEdges[id] = deps;
        }

        // ---- 2. Merged graph = old edges + new edges (a UNION — never overwrite old edges).
        Dictionary<string, List<string>> merged = new Dictionary<string, List<string>>();
        foreach (KeyValuePair<string, List<string>> pair in _dependsOn) merged[pair.Key] = new List<string>(pair.Value);
        foreach (KeyValuePair<string, List<string>> pair in newEdges) {
            if (!merged.ContainsKey(pair.Key)) merged[pair.Key] = new List<string>();
            foreach (string dep in pair.Value) {
                if (!merged[pair.Key].Contains(dep)) merged[pair.Key].Add(dep);
            }
        }

        // ---- 3. Cycle check. If it throws, we have not changed anything.
        Dictionary<string, int> state = new Dictionary<string, int>();   // 1 = on current path, 2 = finished
        if (HasCycle(task.GetId(), merged, state)) {
            throw new CycleException("Adding task '" + task.GetId() + "' creates a cycle.");
        }

        // ---- 4. Commit.
        foreach (KeyValuePair<string, ITask> pair in newTasks) {
            if (_tasks.ContainsKey(pair.Key)) continue;      // already known: keep its state
            _tasks[pair.Key] = pair.Value;
            _dependsOn[pair.Key] = new List<string>();
            _unfinished[pair.Key] = 0;
        }
        foreach (KeyValuePair<string, List<string>> pair in newEdges) {
            string id = pair.Key;
            foreach (string dep in pair.Value) {
                if (_dependsOn[id].Contains(dep)) continue;  // same edge declared twice
                _dependsOn[id].Add(dep);
                if (!_waitingOnMe.ContainsKey(dep)) _waitingOnMe[dep] = new List<string>();
                _waitingOnMe[dep].Add(id);
                if (!_completed.Contains(dep)) _unfinished[id]++;
            }
        }
        foreach (string id in newTasks.Keys) {
            if (_unfinished[id] == 0) MarkReady(id);
        }
    }

    // Depth-first search. Meeting a task that is still "on the current path" means a cycle.
    private static bool HasCycle(string id, Dictionary<string, List<string>> edges, Dictionary<string, int> state) {
        state[id] = 1;
        List<string> deps;
        if (edges.TryGetValue(id, out deps)) {
            foreach (string next in deps) {
                int s;
                state.TryGetValue(next, out s);              // 0 if never visited
                if (s == 1) return true;                     // back on our own path: a cycle
                if (s == 0 && HasCycle(next, edges, state)) return true;
            }
        }
        state[id] = 2;
        return false;
    }

    private void MarkReady(string id) {
        if (_handedOut.Contains(id) || _completed.Contains(id)) return;
        if (_inReadyQueue.Contains(id)) return;              // never queue a task twice
        _inReadyQueue.Add(id);
        _ready.Enqueue(id);
    }

    // The next task whose subtasks are all complete, or null if none is runnable right now.
    public ITask PollNextTask() {
        while (_ready.Count > 0) {
            string id = _ready.Dequeue();
            _inReadyQueue.Remove(id);
            if (_completed.Contains(id)) continue;
            if (_unfinished[id] > 0) continue;               // gained a dependency after it was queued
            if (_handedOut.Contains(id)) continue;           // already given to a worker
            _handedOut.Add(id);
            return _tasks[id];
        }
        return null;
    }

    public void CompleteTask(string id) {
        if (!_tasks.ContainsKey(id)) throw new KeyNotFoundException(id);
        if (_completed.Contains(id)) return;                 // completing twice is harmless
        _completed.Add(id);
        List<string> waiting;
        if (!_waitingOnMe.TryGetValue(id, out waiting)) return;
        foreach (string waiter in waiting) {
            _unfinished[waiter]--;
            if (_unfinished[waiter] == 0) MarkReady(waiter);
        }
    }
}
